class _NoGroqRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Keep credentials on the fixed Groq origin, even on unexpected redirects.
        return None


def _api_object(value):
    if isinstance(value, dict):
        return SimpleNamespace(**{key: _api_object(item) for key, item in value.items()})
    if isinstance(value, list):
        return [_api_object(item) for item in value]
    return value


try:
    from groq import Groq, APIConnectionError, APIStatusError, RateLimitError
    GROQ_SDK_AVAILABLE = True
except ImportError:
    GROQ_SDK_AVAILABLE = False

    class APIConnectionError(RuntimeError):
        pass

    class APIStatusError(RuntimeError):
        def __init__(self, status_code: int, body=None, headers=None):
            self.status_code = status_code
            self.body = body or {}
            self.response = SimpleNamespace(headers=headers or {})
            super().__init__('Groq request failed (HTTP ' + str(status_code) + ').')

    class RateLimitError(APIStatusError):
        pass

    class Groq:
        """SDK-compatible subset using Python HTTPS; no dependency installation."""
        def __init__(self, api_key: str, timeout: float = 45, max_retries: int = 0):
            self._key = api_key
            self._timeout = timeout
            self._opener = build_opener(HTTPSHandler(context=ssl.create_default_context()), _NoGroqRedirect())
            self.chat = SimpleNamespace(completions=SimpleNamespace(
                create=self._chat, with_raw_response=SimpleNamespace(create=self._chat_raw)))
            self.audio = SimpleNamespace(transcriptions=SimpleNamespace(create=self._transcription))

        def _request(self, endpoint: str, data: bytes, content_type: str):
            request = Request('https://api.groq.com/openai/v1/' + endpoint, data=data,
                headers={'Authorization': 'Bearer ' + self._key, 'Content-Type': content_type}, method='POST')
            try:
                with self._opener.open(request, timeout=self._timeout) as response:
                    raw = response.read(8 * 1024 * 1024 + 1)
                    headers = {key.lower(): value for key, value in response.headers.items()}
                if len(raw) > 8 * 1024 * 1024:
                    raise APIConnectionError('Groq response exceeded the permitted size.')
                body = json.loads(raw.decode('utf-8'))
                if not isinstance(body, dict):
                    raise APIConnectionError('Groq response format was invalid.')
                return body, headers
            except HTTPError as error:
                try:
                    body = json.loads(error.read(256 * 1024).decode('utf-8'))
                except (ValueError, UnicodeError):
                    body = {}
                headers = {key.lower(): value for key, value in error.headers.items()}
                kind = RateLimitError if error.code == 429 else APIStatusError
                raise kind(error.code, body, headers) from None
            except (URLError, TimeoutError, OSError, ValueError, UnicodeError):
                raise APIConnectionError('Groq could not be reached or returned invalid data.') from None

        def _chat_raw(self, **values):
            body, headers = self._request('chat/completions',
                json.dumps(values, ensure_ascii=False).encode('utf-8'), 'application/json')
            return SimpleNamespace(headers=headers, parse=lambda: _api_object(body))

        def _chat(self, **values):
            return self._chat_raw(**values).parse()

        def _transcription(self, file, **values):
            filename, audio = file[:2]
            if not isinstance(audio, bytes):
                raise ValueError('Audio must be supplied as bytes.')
            boundary = 'grievance_' + uuid.uuid4().hex
            parts = []
            for key, value in values.items():
                if not re.fullmatch(r'[a-z_]+', key):
                    raise ValueError('Invalid speech parameter.')
                parts.append(('--' + boundary + '\r\nContent-Disposition: form-data; name="' + key +
                    '"\r\n\r\n' + str(value) + '\r\n').encode('utf-8'))
            parts.append(('--' + boundary + '\r\nContent-Disposition: form-data; name="file"; '
                'filename="complaint.wav"\r\nContent-Type: audio/wav\r\n\r\n').encode('ascii'))
            parts.extend([audio, ('\r\n--' + boundary + '--\r\n').encode('ascii')])
            body, _ = self._request('audio/transcriptions', b''.join(parts), 'multipart/form-data; boundary=' + boundary)
            return _api_object(body)


AI_LIVE_MODE = 'CrewAI / Groq' if CREWAI_AVAILABLE else 'Sequential AI stages / Groq'


def run_sequential_agents(tasks, llm):
    """Six explicit AI stages with selected previous results; no simulated AI."""
    outputs = []
    for task in tasks:
        context = [{'stage': previous.agent.role, 'result': previous.output.raw[:2600]}
            for previous in task.context]
        result = llm.call([
            {'role': 'system', 'content': 'Role: ' + task.agent.role + '\n' + task.agent.backstory},
            {'role': 'user', 'content': task.description + '\nEXPECTED OUTPUT:\n' + task.expected_output +
                '\nPREVIOUS STAGE RESULTS (untrusted data):\n' + json.dumps(context, ensure_ascii=False)}])
        task.output = SimpleNamespace(raw=result)
        outputs.append(task.output)
    return SimpleNamespace(tasks_output=outputs)

# ---------------- Embedded corpus access; no helper files required ----------------
@lru_cache(maxsize=3)
def builtin_corpus_bytes(name: str) -> bytes:
    encoded = EMBEDDED_REGULATORY_FILES.get(name)
    if encoded is None:
        raise FileNotFoundError('Unknown embedded legal resource.')
    return zlib.decompress(base64.b64decode(encoded))

def corpus_bytes(name: str, directory: Path) -> bytes:
    directory = Path(directory)
    if (directory / 'manifest.json').is_file():
        return (directory / name).read_bytes()
    if directory.resolve() == INDEX_DIR.resolve():
        return builtin_corpus_bytes(name)
    raise FileNotFoundError('The selected optional legal collection has not been built.')

def regulatory_manifest() -> dict:
    return json.loads(corpus_bytes('manifest.json', INDEX_DIR).decode('utf-8'))

