# The citizen's description often matches a conduct rule without matching the
# separate rules explaining who accepts complaints. Search both questions.
GUIDANCE_QUERIES = {
    'PEMRA': [
        'Filing complaint any person aggrieved by a programme or advertisement may lodge a complaint before Council of Complaints or authorized officer where programme is viewed.',
        'Council shall receive and review complaints about programmes broadcast or distributed by a station through a licence issued by the Authority.'
    ],
    'NEPRA': ['Electricity consumer complaint eligibility filing with NEPRA after complaint to distribution company licensee complaint handling procedure.'],
    'IESCO': ['IESCO electricity billing meter supply complaint registration first contact distribution company customer service.'],
    'PTA': ['PTA consumer complaint registration service provider operator complaint number Complaint Management System procedure.']
}
STOP_WORDS = set('a an and are as at be before by for from has have in is it of on or shall that the their this to under with'.split())


def _words(text: str) -> list[str]:
    return [word for word in re.findall(r'\w+', text.lower())
            if len(word) > 1 and word not in STOP_WORDS]


def _keyword_scores(query: str, chunks: list[dict], allowed: set[int]) -> dict[int, float]:
    """Small BM25-style fallback, using only the validated local corpus."""
    terms = set(_words(query))
    counts = {i: Counter(_words(chunks[i]['text'])) for i in allowed}
    if not terms or not counts:
        return {}
    average = max(1, sum(sum(c.values()) for c in counts.values()) / len(counts))
    frequencies = {term: sum(term in c for c in counts.values()) for term in terms}
    scores = {}
    for i, count in counts.items():
        score = 0.0
        length = sum(count.values())
        for term in terms:
            frequency = count[term]
            if frequency:
                idf = math.log(1 + (len(counts) - frequencies[term] + 0.5) / (frequencies[term] + 0.5))
                score += idf * frequency * 2.2 / (frequency + 1.2 * (0.25 + 0.75 * length / average))
        if score:
            scores[i] = score
    largest = max(scores.values(), default=1)
    return {i: score / largest for i, score in scores.items()}


def _with_context(hit: dict, chunks: list[dict]) -> dict:
    """Join adjacent chunks on the same page so a rule is not cut mid-sentence."""
    page_chunks = sorted((c for c in chunks if
        c['source_file'] == hit['source_file'] and c.get('page') == hit.get('page')),
        key=lambda c: c.get('char_start', 0))
    position = next(i for i, c in enumerate(page_chunks) if c['chunk_id'] == hit['chunk_id'])
    neighbours = page_chunks[max(0, position-1):position+2]
    text = neighbours[0]['text']
    end = neighbours[0].get('char_end', len(text))
    for item in neighbours[1:]:
        start = item.get('char_start', end)
        overlap = max(0, end - start)
        text += ('\n' if start > end else '') + item['text'][overlap:]
        end = item.get('char_end', start + len(item['text']))
    return {**hit, 'text': text, 'char_start': neighbours[0].get('char_start', 0),
            'char_end': end, 'context_chunk_ids': [c['chunk_id'] for c in neighbours]}

@lru_cache(maxsize=2)
def get_embedder(model_name: str = DEFAULT_EMBEDDING_MODEL):
    if not semantic_dependencies_available():
        raise ImportError('Semantic retrieval is optional; install faiss-cpu and fastembed to enable it.')
    from fastembed import TextEmbedding
    return TextEmbedding(model_name=model_name, threads=2, cache_dir=str(ROOT / '.embedding_cache'))

def embed_texts(texts: list[str], model_name: str = DEFAULT_EMBEDDING_MODEL) -> np.ndarray:
    values = np.asarray(list(get_embedder(model_name).embed(texts, batch_size=16)), dtype='float32')
    if values.ndim != 2 or not np.isfinite(values).all():
        raise ValueError('Embedding model returned invalid vectors.')
    values = np.ascontiguousarray(values)
    faiss.normalize_L2(values)
    return values

@lru_cache(maxsize=4)
def _load_index(directory: str, manifest_contents: str):
    folder = Path(directory)
    manifest = json.loads(manifest_contents)
    data = {name: corpus_bytes(name, folder) for name in ['index.faiss', 'chunks.json']}
    for name, contents in data.items():
        if hashlib.sha256(contents).hexdigest() != manifest['sha256'][name]:
            raise ValueError('Index files are incomplete or changed. Restore the supplied file or rebuild the optional index.')
    chunks = json.loads(data['chunks.json'].decode('utf-8'))
    if len(chunks) != manifest['chunk_count']:
        raise ValueError('Legal corpus and metadata do not match.')
    index = faiss.deserialize_index(np.frombuffer(data['index.faiss'], dtype='uint8').copy()) if semantic_dependencies_available() else None
    if index is not None and (index.ntotal != len(chunks) or index.d != manifest['dimensions']):
        raise ValueError('Index and metadata do not match. Rebuild the optional index.')
    return index, chunks, manifest

def search_index(query: str, authority: str | list[str] | None = None, top_k: int = 5, directory: Path = INDEX_DIR) -> list[dict]:
    if not query.strip() or top_k <= 0:
        return []
    manifest_text = corpus_bytes('manifest.json', directory).decode('utf-8')
    index, chunks, manifest = _load_index(str(directory.resolve()), manifest_text)
    authorities = [authority] if isinstance(authority,str) else authority
    allowed = {i for i,c in enumerate(chunks) if authorities is None or c['authority'] in authorities + ['General']}
    if not allowed:
        return []
    intents = [(query, 'complaint', allowed)]
    # A general values objection is not automatically a religious-hatred case.
    # Retrieve the broad programme principles rather than letting the word
    # 'religious' select only news, advertisements or sectarianism passages.
    words = set(_words(query))
    if 'PEMRA' in (authorities or []) and (words & {
        'islam', 'islamic', 'religion', 'religious', 'culture', 'cultural',
        'اسلام', 'اسلامی', 'مذہب', 'مذہبی', 'ثقافت', 'ثقافتی'}):
        intents.append(('Fundamental principles: no content is aired which is against '
            'Islamic values, ideology of Pakistan; general programme content standards.',
            'complaint', allowed))
        intents.append(('Preservation of national cultural social and religious values; '
            'programme standards of decency, obscenity or vulgarity.',
            'complaint', allowed))
    for name in authorities or []:
        scoped = {i for i in allowed if chunks[i]['authority'] in (name, 'General')}
        for guidance in GUIDANCE_QUERIES.get(name, []):
            if scoped:
                intents.append((guidance, 'procedure', scoped))
    try:
        vectors = embed_texts([intent[0] for intent in intents], manifest['embedding_model']) if index is not None else None
    except Exception:
        # A model download/cache failure must not discard readable source text.
        # Hash/index corruption is checked above and is never bypassed here.
        vectors = None
    if vectors is not None and index is not None and vectors.shape[1] != index.d:
        raise ValueError('Query embedding dimension differs from the saved index.')
    rankings = []
    for position, (text, purpose, scoped) in enumerate(intents):
        keywords = _keyword_scores(text, chunks, scoped)
        candidates = []
        if vectors is None:
            scores_ids = sorted(((score, i) for i, score in keywords.items()), reverse=True)
            method = 'keyword_fallback'
        else:
            scores, ids = index.search(vectors[position:position+1], index.ntotal)
            scores_ids = zip(scores[0], ids[0])
            method = 'semantic'
        for score, chunk_id in scores_ids:
            chunk_id = int(chunk_id)
            if chunk_id not in scoped or float(score) < (0.15 if vectors is None else 0.25):
                continue
            candidates.append({**chunks[chunk_id], 'score': round(float(score), 4),
                'ranking_score': float(score) * 0.7 + keywords.get(chunk_id, 0) * 0.3,
                'retrieval_purpose': purpose, 'retrieval_method': method})
        rankings.append(sorted(candidates, key=lambda c: c['ranking_score'], reverse=True))
    results, pages, summaries = [], set(), set()

    def add(item):
        key = (item['source_file'], item.get('page'))
        is_summary = item.get('source_kind') != 'policy_pdf'
        if len(results) >= top_k or key in pages or (is_summary and summaries):
            return False
        results.append(item)
        pages.add(key)
        if is_summary:
            summaries.add(item['source_file'])
        return True

    # Reserve room for the route, one summary and the actual complaint content.
    procedure_slots = min(2, max(0, top_k-2))
    for intent, ranking in zip(intents, rankings):
        if intent[1] != 'procedure':
            continue
        if len(results) >= procedure_slots:
            break
        primary = [c for c in ranking if c.get('source_kind') == 'policy_pdf']
        for item in primary or ranking:
            if add(item):
                break
    all_candidates = sorted([c for ranking in rankings for c in ranking],
                            key=lambda c: c['ranking_score'], reverse=True)
    for item in all_candidates:
        if item.get('source_kind') != 'policy_pdf' and add(item):
            break
    content_rankings = [ranking for intent, ranking in zip(intents, rankings)
                        if intent[1] == 'complaint']
    # Where a content-specific expansion was needed, prefer its general
    # provisions before falling back to the original wording's candidates.
    ordered_content = content_rankings[1:] + content_rankings[:1]
    for ranking in ordered_content:
        for item in [c for c in ranking if c.get('source_kind') == 'policy_pdf']:
            if add(item):
                break
        if len(results) >= top_k:
            break
    content = [item for ranking in ordered_content for item in ranking]
    for item in content + all_candidates:
        add(item)
        if len(results) >= top_k:
            break
    return [_with_context(item, chunks) for item in results]

# Lexical preview for temporary uploads; corpus search normally uses semantic embeddings.
def retrieve(query: str, documents: list[dict], limit: int = 4) -> list[dict]:
    import re
    words = set(re.findall(r'\w+',query.lower()))
    scored = [(len(words & set(re.findall(r'\w+',d['text'].lower()))),d) for d in documents]
    return [d for score,d in sorted(scored,key=lambda x:x[0],reverse=True) if score][:limit]

# ---------------- Private case storage ----------------
DB_PATH = Path(os.environ.get('CASE_DB_PATH', str(Path(__file__).parent / 'cases.sqlite3')))

def owner_hash(token: str) -> str:
    return hashlib.sha256(token.encode()).hexdigest()

@contextmanager
def case_connection():
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(DB_PATH, timeout=10)
    connection.execute('CREATE TABLE IF NOT EXISTS cases (owner TEXT, id TEXT, body TEXT, PRIMARY KEY(owner,id))')
    try:
        DB_PATH.chmod(0o600)
    except OSError:
        pass
    try:
        with connection:
            yield connection
    finally:
        connection.close()

def save_case(token: str, case: dict) -> None:
    with case_connection() as db:
        db.execute('INSERT OR REPLACE INTO cases VALUES (?, ?, ?)', (owner_hash(token), case['id'], json.dumps(case, ensure_ascii=False)))

def load_cases(token: str) -> dict:
    with case_connection() as db:
        rows = db.execute('SELECT id, body FROM cases WHERE owner=?', (owner_hash(token),)).fetchall()
    return {case_id: json.loads(body) for case_id, body in rows}

def delete_case(token: str, case_id: str) -> None:
    with case_connection() as db:
        db.execute('DELETE FROM cases WHERE owner=? AND id=?', (owner_hash(token), case_id))

# ---------------- Complaint application ----------------
def basic_complaint_pdf(case: dict, selected=None, include_identity=False, annex=True) -> bytes:
    """Readable English PDF using standard PDF fonts; no optional PDF packages."""
    body = complaint_body(case, include_identity, selected) if annex else letter_for_destination(case['outputs'][3]['text'].strip(), case)
    if not annex:
        timeline = deadline_letter_basis(case)
        if timeline and timeline.strip() not in body:
            body += timeline
    body = body.translate(str.maketrans({'—': '-', '–': '-', '…': '...', '→': ' to ', '\u202f': ' '}))
    try:
        body.encode('cp1252')
    except UnicodeEncodeError:
        raise ValueError('This text needs an optional Unicode PDF renderer. The complete original text and evidence package remain downloadable.') from None
    lines = []
    for line in body.splitlines():
        lines.extend(textwrap.wrap(line.expandtabs(4), width=88, break_long_words=True) or [''])
    pages = [lines[start:start + 44] for start in range(0, len(lines), 44)] or [[]]
    objects = [None, None, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>']
    page_ids = []
    def literal(value):
        return value.encode('cp1252').replace(b'\\', b'\\\\').replace(b'(', b'\\(').replace(b')', b'\\)')
    for number, page in enumerate(pages, 1):
        page_id = len(objects) + 1
        stream_id = page_id + 1
        page_ids.append(page_id)
        stream = b'BT /F1 16 Tf 48 792 Td (' + literal('Complaint for review') + b') Tj ET\n'
        stream += b'BT /F1 8 Tf 48 774 Td (' + literal('Internal case: ' + case['id'] + ' | Prepared: ' + case.get('date', '')) + b') Tj ET\n'
        stream += b'BT /F1 10 Tf 48 746 Td 15 TL\n'
        for index, line in enumerate(page):
            if index:
                stream += b'T*\n'
            stream += b'(' + literal(line) + b') Tj\n'
        stream += b'ET\nBT /F1 7 Tf 48 30 Td (' + literal('Citizen-prepared complaint. The receiving authority issues the official acknowledgement.') + b') Tj ET\n'
        stream += b'BT /F1 8 Tf 540 30 Td (' + str(number).encode() + b') Tj ET\n'
        objects.append(('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 3 0 R >> >> /Contents ' + str(stream_id) + ' 0 R >>').encode())
        objects.append(b'<< /Length ' + str(len(stream)).encode() + b' >>\nstream\n' + stream + b'endstream')
    objects[0] = b'<< /Type /Catalog /Pages 2 0 R >>'
    objects[1] = ('<< /Type /Pages /Count ' + str(len(page_ids)) + ' /Kids [' + ' '.join(str(identifier) + ' 0 R' for identifier in page_ids) + '] >>').encode()
    output = bytearray(b'%PDF-1.4\n%\xe2\xe3\xcf\xd3\n')
    offsets = [0]
    for identifier, item in enumerate(objects, 1):
        offsets.append(len(output))
        output.extend(str(identifier).encode() + b' 0 obj\n' + item + b'\nendobj\n')
    xref = len(output)
    output.extend(('xref\n0 ' + str(len(objects) + 1) + '\n0000000000 65535 f \n').encode())
    for offset in offsets[1:]:
        output.extend(f'{offset:010d} 00000 n \n'.encode())
    output.extend(('trailer\n<< /Size ' + str(len(objects) + 1) + ' /Root 1 0 R >>\nstartxref\n' + str(xref) + '\n%%EOF\n').encode())
    return bytes(output)

def reviewed_email_material(case: dict, selected: list[str], include_identity: bool,
                            consent: bool, review_token: str) -> tuple[dict, list[dict], str, str]:
    """Validate the exact reviewed material for either client-side email action."""
    if not consent:
        raise ValueError('Review and authorize this exact complaint, recipient and evidence first.')
    if st.session_state.get('demo_mode', False) or case.get('demo_case'):
        raise ValueError('Use a real complaint with Demo mode off before preparing an email for sending.')
    if case.get('letter_needs_review'):
        raise ValueError('Review the updated particulars and letter before preparing email.')
    if review_token != submission_review_token(case, selected, include_identity):
        raise ValueError('The complaint changed after review. Review the current message and files again.')
    route = complaint_destination(case)
    problems = submission_validation(case, route)
    if problems:
        raise ValueError(' '.join(problems))
    if len(selected) != len(set(selected)):
        raise ValueError('Each selected attachment may be included only once.')
    attachments = [item for item in case.get('evidence', []) if item['id'] in selected]
    if len(attachments) != len(selected):
        raise ValueError('The evidence selection changed. Review it again.')
    if any(item['kind'] == CHECKLIST[0] for item in attachments) and not include_identity:
        raise ValueError('Authorize identity sharing or deselect identity documents.')
    subject = re.sub(r'[\r\n]', ' ', case.get('subject') or case.get('intake', {}).get('subcategory') or 'Complaint')[:150]
    subject = 'Complaint ' + case['id'] + ': ' + subject
    return route, attachments, subject, complaint_body(case, include_identity, selected)


def complaint_email_draft(case: dict, selected: list[str], include_identity: bool,
                          consent: bool, review_token: str) -> bytes:
    """An unsent MIME email with actual selected attachments; no network call."""
    from email.policy import SMTP
    route, attachments, subject, body = reviewed_email_material(case, selected, include_identity, consent, review_token)
    message = EmailMessage(policy=SMTP)
    message['From'] = case['profile']['email']
    message['To'] = route['email']
    message['Reply-To'] = case['profile']['email']
    message['Subject'] = subject
    message['X-Unsent'] = '1'
    message['Date'] = formatdate(localtime=False)
    message['Message-ID'] = make_msgid(domain=case['profile']['email'].split('@')[-1])
    message.set_content(body)
    for item in attachments:
        major, minor = item['mime_type'].split('/', 1)
        message.add_attachment(evidence_bytes(item), maintype=major, subtype=minor, filename=item['name'])
    return message.as_bytes()


def complaint_email_links(case: dict, selected: list[str], include_identity: bool,
                          consent: bool, review_token: str) -> dict:
    """Only open a draft after citizen review; long text is never silently cut."""
    from urllib.parse import quote, urlencode
    route, _, subject, body = reviewed_email_material(case, selected, include_identity, consent, review_token)
    def make_links(text):
        return {
            'email_app': 'mailto:' + quote(route['email'], safe='@.') + '?' + urlencode({'subject': subject, 'body': text}, quote_via=quote),
            'gmail': 'https://mail.google.com/mail/?' + urlencode({'view': 'cm', 'fs': '1', 'to': route['email'], 'su': subject, 'body': text}, quote_via=quote),
            'outlook': 'https://outlook.live.com/mail/0/deeplink/compose?' + urlencode({'to': route['email'], 'subject': subject, 'body': text}, quote_via=quote),
        }
    links = make_links(body)
    complete = all(len(value.encode('utf-8')) <= 1800 for value in links.values())
    if not complete:
        links = make_links('Paste the full reviewed complaint from the Public Grievance Assistant here, and attach the selected evidence before sending.')
    return {**links, 'full_body_in_link': complete}


def record_personal_email(case: dict, selected: list[str], include_identity: bool,
                          consent: bool, review_token: str, confirmed: bool,
                          sent_on: date, reference: str = '') -> dict:
    route, attachments, _, _ = reviewed_email_material(case, selected, include_identity, consent, review_token)
    if not confirmed or not isinstance(sent_on, date) or sent_on > pakistan_today():
        raise ValueError('Confirm you sent the email and enter its actual sending date.')
    receipt = {'channel': 'Personal email', 'status': 'Sent by complainant (self-reported)',
        'recipient': route['email'], 'company': canonical_company(case.get('company', '')),
        'receiving_organization': receiving_organization(case), 'submission_target': filing_target(case),
        'destination_key': dispatch_destination(case), 'attachments': [item['name'] for item in attachments],
        'recorded_at': datetime.now(timezone.utc).isoformat(), 'reported_sent_on': sent_on.isoformat(),
        'official_reference': reference.strip()[:100],
        'verification': 'Complainant-reported sending; delivery and official registration are not verified by this app',
        'review_token': review_token}
    previous = case.get('personal_email_submission', {})
    if previous.get('review_token') == review_token and previous.get('reported_sent_on') == sent_on.isoformat():
        return previous
    case.setdefault('personal_email_history', []).append(copy.deepcopy(receipt))
    case['personal_email_submission'] = receipt
    remember_submission(case, receipt)
    transition_case(case, 'Submitted' if reference.strip() else 'Waiting for Response',
        'Complainant confirmed sending from personal email; delivery not independently verified',
        reference=reference.strip()[:100] if reference.strip() else None)
    return receipt


def render_personal_email(case: dict, selected: list[str], include_identity: bool,
                          consent: bool, reviewed: bool, review_token: str, locked: bool) -> None:
    st.subheader('Send using your own email account')
    st.caption('The app prepares the verified recipient, subject, complaint and selected evidence. Review the draft and press Send in your email account. Opening or downloading a draft does not send it.')
    problems = submission_validation(case, complaint_destination(case))
    ready = bool(consent and reviewed and not problems and not case.get('letter_needs_review')
        and not st.session_state.get('demo_mode', False) and not case.get('demo_case') and not locked)
    if not ready:
        st.caption('Complete the listed particulars and confirm both review boxes above to enable email preparation.')
        st.download_button('Download full email draft with selected attachments (.eml)', b'',
            case['id'] + '-unsent-complaint.eml', 'message/rfc822', disabled=True,
            key=case['id'] + '_email_draft')
        return
    try:
        links = complaint_email_links(case, selected, include_identity, True, review_token)
        draft = complaint_email_draft(case, selected, include_identity, True, review_token)
    except ValueError as error:
        st.warning(str(error)); return
    columns = st.columns(3)
    columns[0].link_button('Open my email app', links['email_app'], type='primary')
    columns[1].link_button('Open Gmail draft', links['gmail'])
    columns[2].link_button('Open Outlook draft', links['outlook'])
    if not links['full_body_in_link']:
        st.info('This complaint is too long for a portable email link. The links fill the recipient and subject; copy the complete complaint below into the draft, or open the downloaded .eml file. No complaint text is truncated.')
        st.code(complaint_body(case, include_identity, selected), language=None)
    st.download_button('Download full email draft with selected attachments (.eml)', draft,
        case['id'] + '-unsent-complaint.eml', 'message/rfc822', key=case['id'] + '_email_draft')
    st.caption('The .eml file contains the full message and selected attachments for a compatible email client. Gmail/Outlook web links do not attach files: add the selected evidence manually in webmail, using the complaint package above.')
    previous = case.get('personal_email_submission', {})
    if previous.get('destination_key') == dispatch_destination(case):
        st.success('You recorded sending this email on ' + previous['reported_sent_on'] + '. Delivery and official registration await confirmation.')
    with st.form(case['id'] + '_personal_email_ack_' + review_token[:16]):
        sent_on = st.date_input('Date I sent the email', value=pakistan_today(), max_value=pakistan_today())
        reference = st.text_input('Official complaint reference, if the recipient has issued one', max_chars=100)
        confirmed = st.checkbox('I sent this exact complaint and selected evidence from my email account.')
        save = st.form_submit_button('Record email sent and continue to tracking')
    if save:
        try:
            record_personal_email(case, selected, include_identity, True, review_token, confirmed, sent_on, reference)
            persist(case)
            navigate_to('My Cases')
            st.rerun()
        except ValueError as error:
            st.warning(str(error))

# ---------------- Groq recovery and last successful model ----------------
GROQ_SAFE_PROVIDER_CODES = {
    'model_permission_blocked_org', 'model_permission_blocked_project',
    'model_not_found', 'model_decommissioned', 'access_denied', 'permission_denied',
    'ip_not_allowed', 'account_suspended', 'organization_restricted', 'project_restricted',
}

def safe_groq_provider_details(value) -> dict:
    if not isinstance(value, dict): return {}
    allowed = {'provider_code': GROQ_SAFE_PROVIDER_CODES | {'unspecified'},
        'access_scope': {'organization_model','project_model','general_access'},
        'response_format': {'json','html','text','absent'}}
    return {key: item for key, item in value.items() if key in allowed and isinstance(item, str) and item in allowed[key]}


def groq_provider_details(error) -> dict:
    """Read typed/JSON/string SDK errors, retaining only fixed safe categories."""
    body = getattr(error, 'body', None)
    response_format = 'json' if isinstance(body, dict) else 'absent'
    if isinstance(body, (str, bytes)):
        if isinstance(body, bytes): body = body.decode('utf-8', errors='replace')
        response_format = 'html' if re.match(r'\s*<(?:!doctype|html)', body, re.I) else 'text'
        try:
            body = json.loads(body[:262144])
            response_format = 'json'
        except (ValueError, TypeError):
            body = None
    if not isinstance(body, dict):
        response = getattr(error, 'response', None)
        try:
            body = response.json()
            if isinstance(body, dict): response_format = 'json'
        except (AttributeError, ValueError, TypeError):
            body = {}
    item = body.get('error', body) if isinstance(body, dict) else {}
    if not isinstance(item, dict): item = {}
    code = str(item.get('code') or getattr(error, 'code', '') or '').strip().lower()
    # Also recognize Groq's documented model-permission message when a client
    # preserves its type/message but omits the code. Do not rotate on a generic 403.
    if not code and item.get('type') == 'permissions_error':
        message = item.get('message', '')
        match = re.search(r'\bmodel\b.{0,150}\bblocked at (?:the )?(organization|project) level\b',
            message, re.I) if isinstance(message, str) else None
        if match:
            code = 'model_permission_blocked_' + ('org' if match[1].lower() == 'organization' else 'project')
    code = code if code in GROQ_SAFE_PROVIDER_CODES else 'unspecified'
    scope = {'model_permission_blocked_org':'organization_model',
        'model_permission_blocked_project':'project_model'}.get(code, 'general_access')
    return {'provider_code':code, 'access_scope':scope, 'response_format':response_format}


def groq_key_digest(api_key: str) -> str:
    return hashlib.sha256(('grievance-groq-model-v1:' + api_key).encode()).hexdigest() if api_key else ''


def working_groq_model(api_key: str) -> str:
    """Private cache is scoped to this exact key; never infer success from a draft."""
    digest = groq_key_digest(api_key)
    if not digest: return ''
    try:
        with feature_database() as db:
            row = db.execute('SELECT model FROM groq_working_models WHERE key_digest=?', (digest,)).fetchone()
        model = row[0] if row else ''
        return model if re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_./-]{1,100}', model) else ''
    except (sqlite3.Error, OSError):
        return ''


def remember_working_groq_model(digest: str, model: str) -> None:
    if not re.fullmatch(r'[0-9a-f]{64}', digest) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_./-]{1,100}', model):
        return
    try:
        with feature_database() as db:
            row = db.execute('SELECT model FROM groq_working_models WHERE key_digest=?', (digest,)).fetchone()
            if not row or row[0] != model:
                db.execute('INSERT OR REPLACE INTO groq_working_models VALUES (?,?,?)',
                    (digest, model, datetime.now(timezone.utc).isoformat()))
    except (sqlite3.Error, OSError):
        pass


def forget_working_groq_model(digest: str, model: str) -> None:
    try:
        with feature_database() as db:
            db.execute('DELETE FROM groq_working_models WHERE key_digest=? AND model=?', (digest, model))
    except (sqlite3.Error, OSError):
        pass


def configured_groq_model() -> str:
    model = secret('GROQ_MODEL', DEFAULT_MODEL).removeprefix('groq/') or DEFAULT_MODEL
    return model if re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_./-]{1,100}', model) else DEFAULT_MODEL


def preferred_groq_model(api_key: str) -> str:
    return working_groq_model(api_key) or configured_groq_model()


def groq_retry_choices(case: dict, api_key: str) -> tuple[list[str], str]:
    working = working_groq_model(api_key)
    choices = list(dict.fromkeys(([working] if working else []) +
        [configured_groq_model()] + list(GROQ_TEXT_MODELS) + groq_fallback_models('')))
    tried = set(case.get('ai_models_tried', []))
    default = working if working and working not in tried else next((model for model in choices if model not in tried), choices[0])
    return choices, default


def acknowledge_local_draft(case: dict) -> None:
    """Proceed with the actual template without calling it successful AI output."""
    case['ai_issue_acknowledged_at'] = datetime.now(timezone.utc).isoformat()
    case['mode'] = ('Local template — AI unavailable' if 'template' in case.get('mode', '').lower()
        else 'Prepared complaint — last AI retry unavailable')

