def run_command_line() -> None:
    if '--scheduler' in sys.argv:
        sys.argv.remove('--scheduler')
        raise SystemExit(run_scheduler())
    if '--ingest' in sys.argv:
        sys.argv.remove('--ingest')
        if not semantic_dependencies_available() or PdfReader is None:
            raise SystemExit('Optional indexing needs: python -m pip install faiss-cpu fastembed pypdf tokenizers')
        namespace = dict(globals(), __name__='embedded_ingestion')
        exec(compile(INGESTION_SOURCE, __file__ + ':ingestion', 'exec'), namespace)
        raise SystemExit(namespace['main']())
    main()


if __name__ == '__main__':
    run_command_line()
